#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"#include "Common.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  int nImage;  int nCount;  int nParam;  bool m_bPressed;  CPipeClient* pPipe;  int nSendNOM,nSendMES;  bool bAlways1;  double dNew;  } Queue_Close;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция начального нажатияstatic void fnBeginPress(void* base,void* pVoid)  {  ASS( base )  Queue_Close* p = (Queue_Close*)base;  p->m_bPressed = true;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция посылки сообщенияstatic void fnSendData(void* base,void* pVoid,bool bMessage)  {  ASS( base )  Queue_Close* p = (Queue_Close*)base;  if ( p->nImage == 1 )    {    for ( int n = 0; n < p->nCount; n++ )      {      CShForsunka& sh = (CShForsunka&)p->pPipe->SH(p->nNumber+n);      if ( IsTypeOK )        {        SSendToModel send;        send.eData = id_Forsunka;        void* pVoid = NULL;        double New = p->dNew;        if ( p->nParam == 0 )          pVoid  = FillVoid( send, &sh, "Вентиль газа" );        else        if ( p->nParam == 1 )          pVoid  = FillVoid( send, &sh, "Шибер газа" );		if (p->nParam==2)			pVoid= FillVoid( send, &sh, "Вентиль КЦА газа" );		if (p->nParam==3)			pVoid= FillVoid( send, &sh, "Пилотный вентиль" );        //        if ( pVoid != NULL )          {          send.Set( enumValueDbl, pVoid, &New );          p->pPipe->SendData( p->nNumber+n, send, true );          }        }      }    }  p->m_bPressed = false;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintClose(DefinePaint)  {  QueueP(Queue_Close);  //  if ( p->m_bPressed ) return 1;  //  int nImage = 1;  if (!p->bAlways1)  for ( int n = 0; n < p->nCount; n++ )    {		CShForsunka& sh = (CShForsunka&)q.m_pPipe->SH(p->nNumber+n);		if ( p->nParam == 0 )		  {			  if ( sh.VentGas > 0 )				{				nImage = 0; break;				}		  }		else		if ( p->nParam == 1 )		  {			  if ( sh.ShibGas > 0 )				{				nImage = 0; break;				}		  }		else		if ( p->nParam == 2 )		  {		  }		else		if ( p->nParam == 3 )		  {			  if ( sh.VentPilot > 0 )				{				nImage = 0; break;				}		  }    }  p->nImage = nImage;  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddClose(DefineTegs)  {  AddQueueEx(Queue_Close);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintClose;  //  SPriborInt data;  char szImage[64] = "\0";  POINT pt = {0,0};  data.pBase   = p;  data.fnData  = fnSendData;  data.fnPress = fnBeginPress;  data.pVoid   = &p->nImage;  p->bAlways1=false;  p->dNew=0;  //  STegObj obj[] =    {    { 'S', "image" , szImage, 63 },    { 'P', "pt"    , &pt         },    { 'N', "direct", &data.direct},    { 'D', "scale" , &data.dScale},    { 'I', "type"  , &p->nParam  },	{ 'L', "always1"  , &p->bAlways1  },	{ 'D', "new" , &p->dNew},    // Дополнительная информация    EXT_QUEUE    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );\  p->nCount = Atoi(teg[0].value);  p->pPipe = def.m_queue.m_pPipe;  //  HPRIBOR hPribor = ::GiveMyPribor( szImage, pt, &data );  //  if ( hPribor == NULL )    return;  //  SIZE sz = ::GiveMySize( hPribor );  sz.cx = int(sz.cx*data.dScale);  sz.cy = int(sz.cy*data.dScale);  if ( ::IsMnemoStyle(MNEMO_EDIT) && sz.cx > 0 && sz.cy > 0 )  ::SetRect( &p->mRect, pt.x, pt.y, pt.x+sz.cx, pt.y+sz.cy );  //  def.AddPribor( id_Forsunka, ".", p, hPribor );  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~